import sys; sys.path.insert(0,"/tmp")
from run import *
import subprocess
set_resp()
base="http://127.0.0.1:8765/foo"
def one(args):
    clear(); r=subprocess.run(["./executable"]+args,capture_output=True,text=True,timeout=5)
    rs=reqs()
    if not rs: return f"X{r.returncode}:{r.stderr.strip().split(': ',1)[-1][:60]}"
    h=dict(rs[0]["headers"])
    return f"{rs[0]['method']} {rs[0]['path']} Acc={h.get('Accept')} CT={h.get('Content-Type')} TE={h.get('Transfer-Encoding')} Body={rs[0]['body'][:60]!r}"
combos=[]
for J in [None,True,False]:
 for F in [None,True,False]:
  flags=[]
  if J is not None: flags.append(f"-json={str(J).lower()}")
  if F is not None: flags.append(f"-form={str(F).lower()}")
  combos.append((f"J={J} F={F}",flags))
for meth in ["GET","POST","PUT","DELETE","HEAD","OPTIONS","PATCH"]:
  for items,label in [([],"noitem"),(["a=b"],"data"),(["f@/tmp/upload/test.txt"],"file")]:
    print(f"\n{meth} {label}")
    for label2,flags in combos:
        print(" ",label2, one(flags+[meth,base]+items))
PY
python3 /tmp/table.py > /tmp/table.out 2>&1
cat /tmp/table.out
"}

