		accept = "*/*"
	}
	request.Header.Set("Accept", accept)
	request.Header.Set("Accept-Encoding", "gzip, deflate")
	for key, value := range parsed.headers {
		if key == "Host" {
			request.Host = value
		} else {
			request.Header.Set(key, value)
		}
	}
	if contentType != "" {
		request.Header.Set("Content-Type", contentType)
	}
	if request.Header.Get("User-Agent") == "" {
		request.Header.Set("User-Agent", "bat/0.1.0")
	}
	if authValue != "" {
		username := authValue
		password := ""
		if strings.Contains(authValue, ":") {
			parts := strings.SplitN(authValue, ":", 2)
			username = parts[0]
			password = parts[1]
			if strings.Count(authValue, ":") >= 2 {
				password += ":"
			}
		}
		request.SetBasicAuth(username, password)
	}
	return request, requestBody
}

func magenta(value string) string {
	return "\x1b[95m" + value + "\x1b[0m"
}

func cyan(value string) string {
	return "\x1b[96m" + value + "\x1b[0m"
}

func gray(value string) string {
	return "\x1b[90m" + value + "\x1b[0m"
}

func green(value string) string {
	return "\x1b[92m" + value + "\x1b[0m"
}

func printRequestHeaders(request *http.Request) {
	dump, err := httputil.DumpRequest(request, false)
	if err != nil {
		return
	}
	lines := strings.Split(string(dump), "\n")
	for index, line := range lines {
		if index == 0 {
			parts := strings.Split(line, " ")
			if len(parts) >= 3 {
				fmt.Println(magenta(parts[0]), cyan(parts[1]), magenta(strings.Join(parts[2:], " ")))
			} else {
				fmt.Println(line)
			}
			continue
		}
		if line == "" || line == "\r" {
			break
		}
		parts := strings.SplitN(line, ":", 2)
		if len(parts) == 2 {
			fmt.Println(gray(parts[0]) + ":" + cyan(parts[1]))
		} else {
			fmt.Println(line)
		}
	}
	fmt.Println()
}

func printRequestBody(body []byte) {
	if len(body) == 0 {
		return
	}
	fmt.Println("\r\n" + string(body))
	fmt.Println()
}

func printResponseHeaders(response *http.Response) {
	fmt.Println(magenta(response.Proto), green(response.Status))
	for key, values := range response.Header {
		fmt.Println(gray(key) + ": " + cyan(strings.Join(values, " ")))
	}
	fmt.Println()
}

func readResponseBody(response *http.Response) string {
	var body []byte
	var err error
	if response.Header.Get("Content-Encoding") == "gzip" {
		var gzipReader *gzip.Reader
		gzipReader, err = gzip.NewReader(response.Body)
		if err == nil {
			body, err = io.ReadAll(gzipReader)
			_ = gzipReader.Close()
		}
	} else {
		body, err = io.ReadAll(response.Body)
	}
	if err != nil {
		log.Fatalf("can't get the url %s", err)
	}
	fmt.Println()
	if prettyJSON && jsonContentTypePattern.MatchString(response.Header.Get("Content-Type")) {
		var indented bytes.Buffer
		err = json.Indent(&indented, body, "", "  ")
		if err != nil {
			log.Fatalf("Response Json Indent: %s", err)
		}
		body = indented.Bytes()
	}
	return string(body)
}

func printResponseBody(response *http.Response) {
	body := readResponseBody(response)
	if jsonContentTypePattern.MatchString(response.Header.Get("Content-Type")) {
		fmt.Println(colorizeJSON(body))
	} else {
		fmt.Println(green(body))
	}
}
