{"command":"cat > bench.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"net/http"
	"sort"
	"strings"
	"sync"
	"time"
)

type benchResult struct {
	err           error
	duration      time.Duration
	statusCode    int
	contentLength int64
}

func RunBench(request *http.Request) {
	resultsChannel := make(chan *benchResult, benchN)
	jobs := make(chan struct{})
	var workers sync.WaitGroup
	for index := 0; index < benchC; index++ {
		workers.Add(1)
		go func() {
			defer workers.Done()
			for range jobs {
				start := time.Now()
				response, err := httpClient.Do(request)
				if err != nil {
					resultsChannel <- &benchResult{err: err, duration: time.Since(start)}
					continue
				}
				_, _ = io.Copy(io.Discard, response.Body)
				_ = response.Body.Close()
				contentLength := response.ContentLength
				if contentLength < 0 {
					contentLength = 0
				}
				resultsChannel <- &benchResult{
					duration:      time.Since(start),
					statusCode:    response.StatusCode,
					contentLength: contentLength,
				}
			}
		}()
	}
	go func() {
		for index := 0; index < benchN; index++ {
			jobs <- struct{}{}
		}
		close(jobs)
	}()

	start := time.Now()
	results := make([]*benchResult, 0)
	if benchN > 0 {
		for index := 0; index < benchN; index++ {
			results = append(results, <-resultsChannel)
		}
	}
	totalDuration := time.Since(start)
	workers.Wait()
	printBenchResults(results, totalDuration)
}

func printBenchResults(results []*benchResult, totalDuration time.Duration) {
	latencies := make([]float64, 0)
	statusCodes := make(map[int]int)
	errors := make(map[string]int)
	var totalContentLength int64
	fastest := 0.0
	slowest := 0.0
	for index, result := range results {
		if result.err != nil {
			errors[result.err.Error()]++
			continue
		}
		latency := result.duration.Seconds()
		latencies = append(latencies, latency)
		statusCodes[result.statusCode]++
		totalContentLength += result.contentLength
		if index == 0 || len(latencies) == 1 {
			fastest = latency
			slowest = latency
		}
		if latency < fastest {
			fastest = latency
		}
		if latency > slowest {
			slowest = latency
		}
	}

	if len(latencies) > 0 {
		sort.Float64s(latencies)
		fastest = latencies[0]
		slowest = latencies[len(latencies)-1]
		latencySum := 0.0
		for _, latency := range latencies {
			latencySum += latency
		}
		average := latencySum / float64(len(latencies))
		requestsPerSecond := float64(len(latencies)) / totalDuration.Seconds()

		fmt.Printf("\nSummary:\n")
		fmt.Printf("  Total:\t%4.4f secs.\n", totalDuration.Seconds())
		fmt.Printf("  Slowest:\t%4.4f secs.\n", slowest)
		fmt.Printf("  Fastest:\t%4.4f secs.\n", fastest)
		fmt.Printf("  Average:\t%4.4f secs.\n", average)
		fmt.Printf("  Requests/sec:\t%4.4f\n", requestsPerSecond)
		if totalContentLength > 0 {
			fmt.Printf("  Total Data Received:\t%d bytes.\n", totalContentLength)
			fmt.Printf("  Response Size per Request:\t%d bytes.\n", totalContentLength/int64(len(latencies)))
		}
		fmt.Printf("\nStatus code distribution:\n")
		for code, count := range statusCodes {
			fmt.Printf("  [%d]\t%d responses\n", code, count)
		}
		printBenchHistogram(latencies, fastest, slowest)
		printBenchLatencies(latencies)
	}
	if len(errors) > 0 {
		fmt.Printf("\nError distribution:\n")
		for message, count := range errors {
			fmt.Printf("  [%d]\t%s\n", count, message)
		}
	}
}

func printBenchHistogram(latencies []float64, fastest float64, slowest float64) {
	buckets := make([]int, 11)
	for _, latency := range latencies {
		bucket := 0
		if slowest > fastest {
			bucket = int((latency - fastest) / (slowest - fastest) * 10)
			if bucket < 0 {
				bucket = 0
			}
			if bucket > 10 {
				bucket = 10
			}
		}
		buckets[bucket]++
	}
	maxCount := 0
	for _, count := range buckets {
		if count > maxCount {
			maxCount = count
		}
	}
	fmt.Printf("\nResponse time histogram:\n")
	step := 0.0
	if slowest > fastest {
		step = (slowest - fastest) / 10
	}
	for index, count := range buckets {
		barLength := 0
		if maxCount > 0 {
			barLength = count * 40 / maxCount
		}
		fmt.Printf("  %4.3f [%d]\t|%s\n", fastest+step*float64(index), count, strings.Repeat("∎", barLength))
	}
}

func printBenchLatencies(latencies []float64) {
	percentiles := []int{10, 25, 50, 75, 90, 95, 99}
	fmt.Printf("\nLatency distribution:\n")
	percentileIndex := 0
	for index, latency := range latencies {
		if percentileIndex >= len(percentiles) {
			break
		}
		current := int(float64(index) * 100 / float64(len(latencies)))
		if current >= percentiles[percentileIndex] {
			fmt.Printf("  %d%% in %4.4f secs.\n", percentiles[percentileIndex], latency)
			percentileIndex++
		}
	}
}
EOF
