		}
		if printAll || strings.Contains(printValue, "B") {
			printRequestBody(requestBody)
		}
		if printAll || strings.Contains(printValue, "h") {
			printResponseHeaders(response)
		}
		if printAll || strings.Contains(printValue, "b") {
			printResponseBody(response)
		}
		return
	}

